-- Initial curated catalog (reference content for the new table).
INSERT INTO public.training_modules (slug, title, summary, key_points, media_url, media_label, departments, vessel_families, levels, domains, trading_areas, concepts, quiz, priority) VALUES
('enclosed-space-entry', 'Enclosed Space Entry & Rescue', 'Why enclosed spaces still kill seafarers, and the exact checks before anyone goes in.',
 '["Treat every tank, void, hold and duct keeper as dangerous until tested and permitted.","Ventilate, then test in order: oxygen first (20.9%), then flammables (LEL), then toxic gases (H2S, CO).","Entry needs a signed permit, a trained attendant at the entrance and agreed communication.","The attendant never enters to rescue alone — raise the alarm and wait for the rescue team with breathing apparatus.","SOLAS requires enclosed space entry and rescue drills at least every two months."]',
 'https://www.gov.uk/government/publications/code-of-safe-working-practices-for-merchant-seafarers', 'Code of Safe Working Practices (UK MCA)',
 '{}', '{}', '{}', ARRAY['enclosed space entry','permit to work & ppe','safety','safety culture'], '{}',
 ARRAY['Atmosphere testing order','Attendant duties','Rescue drill frequency'],
 '[{"q":"What oxygen reading is normal before entry is considered?","options":["16%","20.9%","25%","Any reading above 10%"],"correct":1},{"q":"A person collapses inside a tank. What does the attendant do first?","options":["Enter immediately to pull them out","Raise the alarm and wait for the rescue team with breathing apparatus","Close the hatch to contain gas","Lower a rope and keep working"],"correct":1},{"q":"How often must enclosed space entry and rescue drills be held under SOLAS?","options":["Every week","At least every two months","Once per contract","Once per year"],"correct":1}]', 10),

('mooring-snapback', 'Mooring Safety & Snap-Back Zones', 'How mooring lines fail and where to stand so a parting line cannot reach you.',
 '["A parting synthetic line can recoil with enough energy to kill — anywhere near the line path is dangerous.","Painted snap-back zones show only part of the danger area; keep out of the whole line path under tension.","Never stand in the bight of a line or between a line and its fairlead.","Keep clear communication with the bridge and use one person to give signals.","Inspect lines, tails and winch brakes; report worn or chafed lines before use."]',
 'https://www.gov.uk/government/publications/code-of-safe-working-practices-for-merchant-seafarers', 'Code of Safe Working Practices — mooring chapter',
 ARRAY['DECK'], '{}', '{}', ARRAY['mooring','mooring & anchoring','mooring operations safety'], '{}',
 ARRAY['Snap-back danger area','Standing in the bight','Winch brake checks'],
 '[{"q":"Painted snap-back zones on deck…","options":["Show the entire danger area","Show only part of the danger area — stay out of the line path","Are only required on tankers","Mean it is safe to stand anywhere else"],"correct":1},{"q":"Where should you never stand during mooring?","options":["Behind the winch control","In the bight of a line","Next to the deck officer","Out of the line path"],"correct":1},{"q":"What do you do with a badly chafed mooring line?","options":["Use it for the last line","Report it and remove it from use","Turn it end for end and keep using","Nothing if it has not parted"],"correct":1}]', 5),

('colreg-lookout', 'COLREG: Lookout, Crossing & Restricted Visibility', 'The rules officers get wrong under pressure: proper lookout, crossing situations and fog.',
 '["Rule 5: keep a proper lookout at all times by sight and hearing and all available means.","Rule 15: in a crossing situation, the vessel with the other on her own starboard side keeps out of the way.","Rule 19: in restricted visibility, proceed at safe speed and avoid altering to port for a vessel forward of the beam (except when overtaking).","Act early and make substantial alterations so the other ship can see your action.","Radar and AIS help but never replace a visual lookout."]',
 'https://www.imo.org/en/About/Conventions/Pages/COLREG.aspx', 'IMO — COLREG convention',
 ARRAY['DECK'], '{}', '{}', ARRAY['colreg','bridge watchkeeping & colreg','lookout & helm orders','navigation'], '{}',
 ARRAY['Rule 5 lookout','Rule 15 crossing','Rule 19 restricted visibility'],
 '[{"q":"In a crossing situation, who gives way?","options":["The faster ship","The ship with the other on her own starboard side","The larger ship","The ship on the right"],"correct":1},{"q":"A proper lookout under Rule 5 is kept by…","options":["Radar only","AIS only","Sight and hearing and all available means","The pilot"],"correct":2},{"q":"In fog, with a radar target forward of the beam (not overtaking), you should avoid…","options":["Reducing speed","An alteration to port","Sounding fog signals","Calling the Master"],"correct":1}]', 5),

('ecdis-passage-planning', 'ECDIS & Passage Planning', 'Set up ECDIS correctly and check the plan so the route never crosses unsafe water.',
 '["Plan in four stages: appraisal, planning, execution and monitoring.","Set the safety contour from draught, squat and required under-keel clearance.","Run the route check and resolve every alarm before the plan is approved by the Master.","Know your back-up arrangement if ECDIS fails.","Keep watch-alarms and display scale appropriate — do not over-zoom out."]',
 'https://www.imo.org/en/About/Conventions/Pages/International-Convention-on-Standards-of-Training,-Certification-and-Watchkeeping-for-Seafarers-(STCW).aspx', 'IMO — STCW convention',
 ARRAY['DECK'], '{}', ARRAY['Management','Operational'], ARRAY['ecdis & passage planning','navigation & passage planning','navigation electronics'], '{}',
 ARRAY['Four stages of passage planning','Safety contour setting','Route check'],
 '[{"q":"What are the four stages of passage planning?","options":["Load, sail, arrive, discharge","Appraisal, planning, execution, monitoring","Chart, radar, GPS, log","Pilot, berth, cargo, sail"],"correct":1},{"q":"The safety contour should be based on…","options":["The deepest water on the chart","Draught, squat and required under-keel clearance","The pilot''s opinion","Default factory settings"],"correct":1},{"q":"Before the route is approved you must…","options":["Ignore minor alarms","Run the route check and resolve all alarms","Switch off depth alarms","Print the chart"],"correct":1}]', 5),

('ows-oil-record-book', 'Oily Water Separator & Oil Record Book', 'MARPOL Annex I compliance that keeps engineers out of court.',
 '["Overboard discharge of oily bilge water must not exceed 15 ppm and needs a working 15 ppm alarm and auto-stop.","Never bypass the OWS — a ''magic pipe'' is a criminal offence in many port states.","Every operation goes in the Oil Record Book Part I, signed by the officer in charge; each page is signed by the Master.","The Oil Record Book must be kept on board for three years.","Sludge goes to the incinerator or shore — record quantities accurately."]',
 'https://www.imo.org/en/OurWork/Environment/Pages/OilPollution-Default.aspx', 'IMO — Prevention of pollution by oil',
 ARRAY['ENGINE'], '{}', '{}', ARRAY['oily water separator & orb','bilge & oily water handling','marpol','marpol annex i/vi compliance','marpol record keeping','marpol pollution prevention','oil spill & garbage handling'], '{}',
 ARRAY['15 ppm limit','ORB signing','Record retention'],
 '[{"q":"What is the oil content limit for overboard discharge from the OWS?","options":["100 ppm","50 ppm","15 ppm","No limit at sea"],"correct":2},{"q":"Who signs each page of the Oil Record Book Part I?","options":["The Chief Cook","The Master","The port agent","Nobody"],"correct":1},{"q":"How long must the Oil Record Book be kept on board?","options":["Six months","One year","Three years","Until the next drydock"],"correct":2}]', 5),

('imsbc-liquefaction', 'Bulk Cargo Liquefaction (IMSBC Group A)', 'How cargoes like nickel ore and iron ore fines can turn liquid and capsize a bulk carrier.',
 '["Group A cargoes may liquefy if moisture content is above the Transportable Moisture Limit (TML).","The shipper must provide a moisture certificate; moisture content must be below the TML.","The can test is only a shipboard check — if free water appears, stop loading and report.","Do not load in heavy rain; keep hatches closed.","Watch for cargo shift, free water on the surface or a list."]',
 'https://www.imo.org/en/OurWork/Safety/Pages/CargoesInBulk-default.aspx', 'IMO — Carriage of cargoes in bulk',
 ARRAY['DECK'], ARRAY['BULK','GENERAL_CARGO'], '{}', ARRAY['cargo operations & stability','cargo','cargo watch','cargo securing'], '{}',
 ARRAY['TML','Can test','Group A cargo'],
 '[{"q":"A Group A cargo can be safely loaded when moisture content is…","options":["Above the TML","Below the TML","Exactly at flow point","Not measured"],"correct":1},{"q":"The can test shows free water on the sample. What do you do?","options":["Continue loading","Stop loading and report","Add more cargo to dry it","Open hatches to let it dry"],"correct":1},{"q":"Who must provide the moisture certificate?","options":["The ship","The shipper","The pilot","The P&I club"],"correct":1}]', 5),

('tanker-inert-gas', 'Tanker Cargo Tanks & Inert Gas', 'Keeping tank atmospheres non-flammable during loading, discharge and tank cleaning.',
 '["Cargo tanks served by inert gas must be kept at an oxygen content of 8% by volume or less.","Maintain positive pressure in tanks — never draw a vacuum during discharge.","Check the P/V valves and breakers are working before cargo operations.","Follow the ship/shore safety checklist and agreed loading rates.","Gas-free certificates are needed before tank entry or hot work."]',
 'https://www.imo.org/en/About/Conventions/Pages/International-Convention-for-the-Safety-of-Life-at-Sea-(SOLAS),-1974.aspx', 'IMO — SOLAS convention',
 ARRAY['DECK','ENGINE'], ARRAY['OIL_TANKER','CHEM_TANKER'], '{}', ARRAY['cargo operations & stability','pumps and cargo pumping','cargo','cargo watch'], '{}',
 ARRAY['8% oxygen limit','Positive tank pressure','Ship/shore checklist'],
 '[{"q":"Maximum oxygen content in inerted cargo tanks?","options":["21%","15%","8% by volume","0%"],"correct":2},{"q":"During discharge the tank pressure should be…","options":["Kept positive","Allowed to go into vacuum","Ignored","Vented to atmosphere"],"correct":0},{"q":"Before cargo operations, which document is completed with the terminal?","options":["Crew list","Ship/shore safety checklist","Garbage record book","Medical log"],"correct":1}]', 5),

('sire-2-readiness', 'SIRE 2.0 — Being Inspected as a Crew Member', 'What the inspector now observes and asks: how you work, not just what is on paper.',
 '["SIRE 2.0 inspectors observe tasks and interview crew, including ratings and junior officers.","Answers should match how the ship actually works under your SMS.","Photos and objective evidence are recorded in the report.","Explain what you are doing and why — show competence, not memorised text.","Human factors (communication, teamwork, workload) are assessed."]',
 'https://www.ocimf.org/programmes/sire-2-0', 'OCIMF — SIRE 2.0 programme',
 '{}', ARRAY['OIL_TANKER','CHEM_TANKER','LNG','LPG'], '{}', ARRAY['ism & psc/vetting','solas safety management','teamwork','communication'], '{}',
 ARRAY['Observed competence','Crew interviews','Human factors'],
 '[{"q":"Under SIRE 2.0, who may the inspector interview?","options":["Only the Master","Only the Chief Officer","Crew at different ranks, including ratings","Nobody — documents only"],"correct":2},{"q":"Good SIRE 2.0 answers…","options":["Are memorised from a list","Match how the ship really works under the SMS","Are left to the Master","Avoid explaining"],"correct":1},{"q":"Which area is now explicitly assessed?","options":["Crew salaries","Human factors like communication and teamwork","Cargo prices","Port fees"],"correct":1}]', 5),

('lockout-tagout', 'Lock-Out / Tag-Out & Electrical Isolation', 'Isolate, lock, tag and prove dead — every time, before touching equipment.',
 '["Identify all energy sources: electrical, hydraulic, pneumatic, stored pressure, gravity.","Isolate, lock and tag each point; each person working fits their own lock.","Prove zero energy with a tested instrument before work starts (test before touch).","High-voltage work needs a permit and a competent person.","Remove locks only when work is complete and everyone is clear."]',
 'https://www.gov.uk/government/publications/code-of-safe-working-practices-for-merchant-seafarers', 'Code of Safe Working Practices — electrical safety',
 ARRAY['ENGINE','ETO'], '{}', '{}', ARRAY['lock-out tag-out','safety & lock-out tag-out','high-voltage safety','electrical fire prevention','insulation testing','generators & switchboards'], '{}',
 ARRAY['Energy isolation','Personal locks','Prove dead'],
 '[{"q":"After isolating and locking, what must you do before work?","options":["Start work immediately","Prove zero energy with a tested instrument","Remove the tag","Ask the cook"],"correct":1},{"q":"With three people working on the equipment…","options":["One lock is enough","Each person fits their own lock","No lock needed if tagged","Only the Chief Engineer locks"],"correct":1},{"q":"Which is a stored energy source?","options":["Pressurised hydraulic accumulator","Paint","Rope","Chart"],"correct":0}]', 5),

('engine-room-fire', 'Engine Room Fire & Fixed CO2 Release', 'The actions in the first minutes and the steps before releasing fixed CO2.',
 '["Raise the alarm, fight small fires early only if safe, and report to the bridge.","Stop fuel supply with remote quick-closing valves and stop ventilation fans.","Before CO2 release: evacuate the space and account for every person, close all openings.","Never re-enter early after CO2 — wait for cooling and re-test the atmosphere.","Know your muster station and duties on the muster list."]',
 'https://www.gov.uk/government/publications/code-of-safe-working-practices-for-merchant-seafarers', 'Code of Safe Working Practices — fire precautions',
 '{}', '{}', '{}', ARRAY['engine room emergencies','fire prevention','emergency','emergency response','emergency duties','galley fire safety'], '{}',
 ARRAY['Quick-closing valves','Headcount before CO2','Re-entry precautions'],
 '[{"q":"Before releasing fixed CO2 into the engine room you must…","options":["Leave the fans running","Evacuate the space and account for everyone","Open the skylight","Start the main engine"],"correct":1},{"q":"How is fuel supply to an engine room fire stopped?","options":["By the remote quick-closing valves","By opening the purifier","By turning off lights","It cannot be stopped"],"correct":0},{"q":"After CO2 release, when can the team re-enter?","options":["Immediately","After cooling and atmosphere testing","After 5 minutes","When smoke stops"],"correct":1}]', 8),

('lsa-ffa-drills', 'Life-Saving Appliances & Drills', 'Drill frequencies and checks every crew member must know for PSC and real emergencies.',
 '["Each crew member takes part in at least one abandon-ship drill and one fire drill every month.","Each lifeboat is launched with its crew at least once every three months where practicable.","Know your muster station, lifeboat and duty on the muster list.","Check lifejackets, immersion suits and EPIRB/SART are in date and in place.","Report any defect in LSA immediately."]',
 'https://www.imo.org/en/About/Conventions/Pages/International-Convention-for-the-Safety-of-Life-at-Sea-(SOLAS),-1974.aspx', 'IMO — SOLAS chapter III',
 '{}', '{}', '{}', ARRAY['lsa/ffa & drills','lsa/ffa maintenance','emergency duties'], '{}',
 ARRAY['Monthly drills','Lifeboat launching interval','Muster list duties'],
 '[{"q":"How often must each crew member join an abandon-ship drill?","options":["Every month","Every six months","Once per contract","Every year"],"correct":0},{"q":"Lifeboats should be launched with their crew at least every…","options":["Week","Three months","Two years","Five years"],"correct":1},{"q":"Where do you find your emergency duty?","options":["The muster list","The menu","The crew agreement","The cargo plan"],"correct":0}]', 6),

('galley-food-safety', 'Galley Food Safety & Hygiene (MLC)', 'Safe storage temperatures, cross-contamination and the MLC food standard.',
 '["MLC 2006 requires food and drinking water of suitable quantity, nutritional value and quality.","Chilled food is kept at 5°C or below and frozen food at -18°C or below.","Keep raw and cooked food separate — separate boards and utensils.","Use HACCP: identify critical points and record temperatures.","Wash hands and report illness before handling food."]',
 'https://www.ilo.org/international-labour-standards/maritime-labour-convention-2006', 'ILO — Maritime Labour Convention 2006',
 ARRAY['CATERING'], '{}', '{}', ARRAY['food safety & haccp','hygiene & sanitation','galley fire safety','mlc 2006 food & catering standards','provisions & storage'], '{}',
 ARRAY['Storage temperatures','Cross-contamination','HACCP records'],
 '[{"q":"Frozen food should be stored at…","options":["0°C","-5°C","-18°C or below","+5°C"],"correct":2},{"q":"Raw chicken and salad should be prepared…","options":["On the same board","With separate boards and utensils","Together to save time","Only by the Master"],"correct":1},{"q":"HACCP is a system to…","options":["Plan menus","Control food safety hazards at critical points","Order provisions","Count crew"],"correct":1}]', 5),

('bunkering-safety', 'Bunkering Safety & Fuel Compliance', 'Preventing spills during bunkering and meeting MARPOL Annex VI sulphur limits.',
 '["Agree the plan, pumping rate and emergency stop signal with the supplier before starting.","Plug scuppers, keep SOPEP equipment ready and watch tank levels continuously.","Never fill a tank beyond the agreed limit (commonly about 90%).","Global sulphur limit is 0.50%; in Emission Control Areas it is 0.10%.","Keep the bunker delivery note and sample as required."]',
 'https://www.imo.org/en/OurWork/Environment/Pages/OilPollution-Default.aspx', 'IMO — Prevention of pollution by oil',
 ARRAY['ENGINE'], '{}', '{}', ARRAY['bunkering & fuel management','purifiers & fuel treatment','marpol annex i/vi compliance'], '{}',
 ARRAY['Pre-bunker agreement','Scuppers and SOPEP','Sulphur limits'],
 '[{"q":"What is the sulphur limit inside an Emission Control Area?","options":["3.50%","0.50%","0.10%","No limit"],"correct":2},{"q":"Before bunkering starts, scuppers should be…","options":["Open","Plugged","Removed","Painted"],"correct":1},{"q":"What must be agreed with the supplier before pumping?","options":["The menu","Pumping rate and emergency stop signal","Crew change","Cargo plan"],"correct":1}]', 5),

('hot-work-safety', 'Hot Work Permits & Fire Watch', 'Welding and cutting safely: permits, gas testing and fire watch.',
 '["Hot work outside the workshop needs a permit approved by the responsible officer.","Remove or protect combustibles and check adjacent spaces, including the other side of bulkheads.","Test the atmosphere where flammable vapours may be present.","A fire watch with extinguisher is kept during the work and continues for a period after finishing.","Close the permit only when the area has been checked safe."]',
 'https://www.gov.uk/government/publications/code-of-safe-working-practices-for-merchant-seafarers', 'Code of Safe Working Practices — hot work',
 ARRAY['ENGINE','DECK'], '{}', '{}', ARRAY['hot work & welding safety','tools & workshop safety','fire prevention'], '{}',
 ARRAY['Hot work permit','Adjacent space checks','Fire watch after work'],
 '[{"q":"Welding on deck outside the workshop requires…","options":["Nothing","A hot work permit","Only gloves","Pilot permission"],"correct":1},{"q":"When does the fire watch stop?","options":["When the welder stops","Only after a period following completion when the area is checked safe","Before work starts","Never needed"],"correct":1},{"q":"Before welding on a bulkhead you must also check…","options":["The space on the other side","The weather only","The galley menu","Crew wages"],"correct":0}]', 5),

('psc-readiness', 'Port State Control Readiness', 'How PSC inspections work and the common deficiencies that lead to detention.',
 '["PSC officers can detain a ship until serious deficiencies are corrected.","Common detainable areas: fire safety, life-saving appliances, ISM, MARPOL and MLC.","Crew must show they can carry out emergency duties — drills may be requested.","Keep certificates, records and logbooks consistent with what is on board.","Report defects through the SMS before the port, not to the inspector."]',
 'https://www.imo.org/en/OurWork/MSAS/Pages/PortStateControl.aspx', 'IMO — Port State Control',
 '{}', '{}', ARRAY['Management','Operational'], ARRAY['ism & psc/vetting','planned maintenance & ism','solas safety management','reporting'], '{}',
 ARRAY['Detention','Common deficiencies','Operational drills'],
 '[{"q":"A PSC officer finds a serious safety deficiency. The ship can be…","options":["Fined only","Detained until it is corrected","Ignored","Sold"],"correct":1},{"q":"PSC may ask crew to…","options":["Show they can perform emergency duties in a drill","Pay a fee","Change flag","Sign off"],"correct":0},{"q":"Defects found on board should be…","options":["Hidden","Reported through the SMS","Reported only after inspection","Ignored if minor"],"correct":1}]', 4),

('amsa-pilot-transfer', 'AMSA Port State Focus: Pilot Transfer Arrangements', 'Australian PSC detains ships for unsafe pilot ladders — rig them right first time.',
 '["Pilot ladders must comply with SOLAS V/23 and be certified and in good condition.","A pilot ladder alone may be used for a climb of not more than 9 metres; above that a combination arrangement is needed.","Steps must be horizontal, secured to strong points (not to rails), with man-ropes and lifebuoy ready.","A responsible officer supervises rigging and the transfer, with communication to the bridge.","AMSA publishes PSC focus areas — check before arrival in Australia."]',
 'https://www.amsa.gov.au/vessels-operators/port-state-control', 'AMSA — Port State Control',
 ARRAY['DECK'], '{}', '{}', ARRAY['ism & psc/vetting','deck maintenance','safety'], ARRAY['AMSA'],
 ARRAY['SOLAS V/23','9 metre climb limit','Supervising officer'],
 '[{"q":"A pilot ladder alone may be used for a climb of not more than…","options":["5 m","9 m","15 m","Any height"],"correct":1},{"q":"Pilot ladders must be secured to…","options":["Ship''s rails","Strong points on deck","The pilot''s boat","Any available pipe"],"correct":1},{"q":"Who supervises rigging and the pilot transfer?","options":["A responsible officer","The pilot","Nobody","The cook"],"correct":0}]', 4),

('uscg-environmental', 'USCG Port State Focus: Ballast Water & Oily Waste', 'US enforcement priorities: ballast water management and oily waste integrity.',
 '["Ships must follow the approved Ballast Water Management Plan and keep the ballast water record book.","Ballast water exchange or an approved treatment system must be used as required.","OWS bypass or falsified Oil Record Book entries are prosecuted criminally in the US.","Crew should report concerns through company channels; whistleblower protection exists.","Records must match tank soundings and equipment logs."]',
 'https://www.imo.org/en/OurWork/Environment/Pages/BallastWaterManagement.aspx', 'IMO — Ballast Water Management',
 ARRAY['DECK','ENGINE'], '{}', '{}', ARRAY['marpol','marpol record keeping','bilge & oily water handling','oily water separator & orb'], ARRAY['USCG'],
 ARRAY['Ballast water record book','OWS integrity','Matching records'],
 '[{"q":"Falsifying the Oil Record Book in a US port can lead to…","options":["Nothing","Criminal prosecution","A verbal warning only","A discount"],"correct":1},{"q":"Ballast operations are recorded in…","options":["The ballast water record book","The deck log only","The menu","Not recorded"],"correct":0},{"q":"Records must match…","options":["Tank soundings and equipment logs","Crew birthdays","The weather","The agent''s invoice"],"correct":0}]', 4),

('paris-tokyo-psc', 'Paris & Tokyo MOU Inspections', 'What European and Asia-Pacific PSC regimes look at and how ships are targeted.',
 '["Paris MOU (Europe/North Atlantic) and Tokyo MOU (Asia-Pacific) share inspection results to target higher-risk ships.","Ship risk profile depends on type, age, flag, company performance and history.","Concentrated Inspection Campaigns focus on one topic for three months — check the current topic before arrival.","Repeated detentions can lead to banning from the region.","Keep ISM records and drills real and up to date."]',
 'https://www.parismou.org/', 'Paris MOU',
 '{}', '{}', ARRAY['Management','Operational'], ARRAY['ism & psc/vetting','solas safety management','planned maintenance & ism'], ARRAY['PARIS_MOU','TOKYO_MOU'],
 ARRAY['Ship risk profile','Concentrated Inspection Campaigns','Banning'],
 '[{"q":"A Concentrated Inspection Campaign usually lasts…","options":["One day","Three months","Five years","It never ends"],"correct":1},{"q":"Ship risk profile considers…","options":["Type, age, flag and company performance","Crew nationality only","The cargo price","The menu"],"correct":0},{"q":"Repeated detentions in the Paris MOU region can lead to…","options":["A reward","A ban from the region","Faster clearance","Nothing"],"correct":1}]', 4);